done = Falselc = ''v = 0while not done:    s = input('Word or phrase: ')    tval = 0    if len(s) == 0:        done = True    else:        for c in s:            C = c.upper()            if C >= 'A' and C <= 'Z':                if len(lc) > 0:                    val = int(lc)                    print('{} {}'.format(lc, val))                    lc = ''                    tval += val                val = ord(C)-64                tval += val                print('{} {}'.format(C, val))            elif c >= '0' and c <= '9':                lc = lc + c        if len(lc) > 0:            val = int(lc)            tval += val            print('{} {}'.format(val, val))            lc = ''        print('Total: {}'.format(tval))